    private void ensureWeb(){if(web!=null)return;web=new WebView(this);web.setBackgroundColor(PAPER);configure(web);web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){Uri u=r.getUrl();if(trusted(u))return false;external(u);return true;}@Override public void onPageFinished(WebView w,String url){super.onPageFinished(w,url);if(trusted(Uri.parse(url))){applyAppLayout();if(errorPanel!=null)errorPanel.setVisibility(View.GONE);}}@Override public void onReceivedError(WebView w,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())showError();}@Override public void onReceivedHttpError(WebView w,WebResourceRequest r,WebResourceResponse e){if(r.isForMainFrame()&&e.getStatusCode()>=400)showError();}@Override public void onReceivedSslError(WebView w,SslErrorHandler handler,SslError error){handler.cancel();showError();}});web.setWebChromeClient(new AppChrome(false));if(restoreWeb!=null){web.restoreState(restoreWeb);restoreWeb=null;}}
