    private class AppChrome extends WebChromeClient{private final boolean document;AppChrome(boolean d){document=d;}@Override public void onProgressChanged(WebView w,int value){if(!document&&progress!=null){progress.setProgress(value);progress.setVisibility(value==100?View.GONE:View.VISIBLE);}}@Override public boolean onShowFileChooser(WebView w,ValueCallback<Uri[]> callback,FileChooserParams params){if(chooser!=null)chooser.onReceiveValue(null);chooser=callback;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/jpeg","image/png","image/webp"});i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);try{startActivityForResult(i,PICK_PHOTOS);}catch(ActivityNotFoundException e){chooser.onReceiveValue(null);chooser=null;Toast.makeText(MainActivity.this,text("No file picker is available","لا يوجد منتقي ملفات"),Toast.LENGTH_LONG).show();}return true;}@Override public boolean onCreateWindow(WebView w,boolean dialog,boolean gesture,Message result){if(!gesture)return false;openDocument(result);return true;}}
    private void openDocument(Message result){if(documentDialog!=null)documentDialog.dismiss();documentDialog=new Dialog(this,android.R.style.Theme_Material_Light_NoActionBar);LinearLayout page=column();LinearLayout bar=new LinearLayout(this);TextView close=action(text("Close","إغلاق"),()->documentDialog.dismiss(),true),print=action(text("Print / Save PDF","طباعة / حفظ PDF"),()->{if(documentWeb!=null){PrintManager m=(PrintManager)getSystemService(PRINT_SERVICE);m.print("ENGINEX quotation",documentWeb.createPrintDocumentAdapter("ENGINEX quotation"),new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).build());}},false);bar.addView(close,new LinearLayout.LayoutParams(0,-2,1));bar.addView(print,new LinearLayout.LayoutParams(0,-2,1));page.addView(bar);documentWeb=new WebView(this);configure(documentWeb);documentWeb.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){String scheme=r.getUrl().getScheme();if("about".equals(scheme))return false;external(r.getUrl());return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){if(!"about".equals(r.getUrl().getScheme()))return new WebResourceResponse("text/plain","utf-8",new ByteArrayInputStream(new byte[0]));return null;}});documentWeb.setWebChromeClient(new AppChrome(true));page.addView(documentWeb,new LinearLayout.LayoutParams(-1,0,1));documentDialog.setContentView(page);documentDialog.setOnDismissListener(d->{if(documentWeb!=null){documentWeb.destroy();documentWeb=null;}documentDialog=null;});documentDialog.show();WebView.WebViewTransport transport=(WebView.WebViewTransport)result.obj;transport.setWebView(documentWeb);result.sendToTarget();}
    private void external(Uri uri){String scheme=uri.getScheme();if(!"https".equals(scheme)&&!"mailto".equals(scheme)&&!"tel".equals(scheme))return;Intent intent=new Intent("tel".equals(scheme)?Intent.ACTION_DIAL:Intent.ACTION_VIEW,uri);try{startActivity(intent);}catch(ActivityNotFoundException e){Toast.makeText(this,text("No compatible app found","لم يتم العثور على تطبيق مناسب"),Toast.LENGTH_LONG).show();}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=PICK_PHOTOS||chooser==null)return;Uri[] uris=null;if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null){int count=Math.min(3,data.getClipData().getItemCount());uris=new Uri[count];for(int i=0;i<count;i++)uris[i]=data.getClipData().getItemAt(i).getUri();}else if(data.getData()!=null)uris=new Uri[]{data.getData()};}chooser.onReceiveValue(uris);chooser=null;}
    @Override public void onBackPressed(){if(documentDialog!=null){documentDialog.dismiss();return;}if(selected!=HOME){show(HOME);return;}super.onBackPressed();}
    @Override protected void onSaveInstanceState(Bundle out){out.putInt("tab",selected);out.putString("section",section);if(web!=null){Bundle state=new Bundle();web.saveState(state);out.putBundle("web",state);}super.onSaveInstanceState(out);}
