    private class ServiceArt extends Drawable{private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);private final int index;ServiceArt(int i){index=i;}@Override public void draw(Canvas canvas){Rect b=getBounds();canvas.drawColor(INK);if(atlas!=null){int width=atlas.getWidth()/3,height=atlas.getHeight()/2;float scale=Math.max((float)b.width()/width,(float)b.height()/height);float cropW=b.width()/scale,cropH=b.height()/scale;int x=(index%3)*width+(int)((width-cropW)/2),y=(index/3)*height+(int)((height-cropH)/2);paint.setShader(null);canvas.drawBitmap(atlas,new Rect(x,y,x+(int)cropW,y+(int)cropH),b,paint);}paint.setShader(new LinearGradient(arabic?b.right:b.left,0,arabic?b.left:b.right,0,new int[]{0xf214282c,0xbb14282c,0x2414282c},new float[]{0,.5f,1},Shader.TileMode.CLAMP));canvas.drawRect(b,paint);paint.setShader(null);}@Override public void setAlpha(int a){paint.setAlpha(a);}@Override public void setColorFilter(ColorFilter f){paint.setColorFilter(f);}@Override public int getOpacity(){return PixelFormat.OPAQUE;}}
